actions.script:
ec.logger.info("================================================================================")
ec.logger.info("🚀 [recordAndDispatch#PipelineStep] INCOMING DISPATCH REQUEST")
ec.logger.info("   discussionId      : ${discussionId}")
ec.logger.info("   pipelineStepId    : ${pipelineStepId}")
ec.logger.info("   parentStepId      : ${parentStepId}")
ec.logger.info("   stanceEnumId      : ${stanceEnumId}")
ec.logger.info("   ingressPayloadId  : ${ingressPayloadId}")
ec.logger.info("   targetArtifactUri : ${targetArtifactUri}")
ec.logger.info("   aiProfileName     : ${aiProfileName}")
ec.logger.info("   directivePrompt   : ${directivePrompt?.take(120)}...")
ec.logger.info("================================================================================")

def disc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
    .condition("discussionId", discussionId)
    .one()
if (!disc) { 
    ec.logger.error("❌ [recordAndDispatch#PipelineStep] Discussion #${discussionId} not found in database!")
    ec.message.addError("Discussion ${discussionId} not found")
    return 
}
String comp = disc.targetComponent ?: "nursinghome"

// ---------------------------------------------------------------------
// AI PROFILE RESOLUTION
// ---------------------------------------------------------------------
String effectiveProfile = aiProfileName
if (!effectiveProfile) {
    def profileFacet = ec.entity.find("org.moqui.ai.discussion.AgiDiscussionFacet")
        .condition("discussionId", discussionId)
        .condition("facetKey", "in", ["aiProfile", "modelProfile", "profile"])
        .one()
    if (profileFacet?.facetValue) {
        effectiveProfile = profileFacet.facetValue
        ec.logger.info("🔎 [recordAndDispatch#PipelineStep] Resolved profile from AgiDiscussionFacet: '${effectiveProfile}'")
    }
}
if (!effectiveProfile) {
    effectiveProfile = ec.user.getPreference("${comp}.ai.profile") ?:
                       System.getProperty("${comp}.ai.profile") ?:
                       System.getProperty("agi.ai.default.profile")
    if (effectiveProfile) {
        ec.logger.info("🔎 [recordAndDispatch#PipelineStep] Resolved profile from System/User preference: '${effectiveProfile}'")
    }
}
if (!effectiveProfile) {
    try {
        def facade = ec.llm
        if (facade != null && facade.getProfileNames()?.size() > 0) {
            effectiveProfile = facade.getDefault()?.getProfileName() ?: "gemini"
            ec.logger.info("🔎 [recordAndDispatch#PipelineStep] Fallback profile from ec.llm default: '${effectiveProfile}'")
        }
    } catch (Exception ignore) {
        effectiveProfile = "gemini"
    }
}
ec.logger.info("🎯 [recordAndDispatch#PipelineStep] FINAL EFFECTIVE AI PROFILE: '${effectiveProfile}'")

// Map stanceEnumId string to mode code (e.g., AamPlan -> plan)
String modeCode = "plan"
if (stanceEnumId == "AamBuild" || stanceEnumId == "build") modeCode = "build"
else if (stanceEnumId == "AamDiscuss" || stanceEnumId == "discuss") modeCode = "discuss"

String normalizedStance = stanceEnumId
if (normalizedStance == "plan") normalizedStance = "AamPlan"
else if (normalizedStance == "build") normalizedStance = "AamBuild"
else if (normalizedStance == "discuss") normalizedStance = "AamDiscuss"

// 1. Resolve Existing Step or Create New Pipeline Step
def currentStep = null
if (pipelineStepId) {
    currentStep = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
        .condition("pipelineStepId", pipelineStepId)
        .one()
}

if (currentStep) {
    ec.logger.info("🔄 [recordAndDispatch#PipelineStep] Re-using and fulfilling existing step #${currentStep.pipelineStepId}")
    currentStep.statusId = "PlsExecuting"
    currentStep.stanceEnumId = normalizedStance
    if (directivePrompt) currentStep.directivePrompt = directivePrompt
    if (stepLabel) currentStep.stepLabel = stepLabel
    if (ingressPayloadId) currentStep.ingressPayloadId = ingressPayloadId
    if (targetArtifactUri) currentStep.targetArtifactUri = targetArtifactUri
    currentStep.lastUpdatedDate = ec.user.nowTimestamp
    currentStep.update()
} else {
    int nextSeq = 1
    def lastStep = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
        .condition("discussionId", discussionId)
        .orderBy("-stepSequenceNum")
        .limit(1)
        .one()
    if (lastStep?.stepSequenceNum) {
        nextSeq = ((lastStep.stepSequenceNum as Integer) ?: 0) + 1
    }

    currentStep = ec.entity.makeValue("org.moqui.ai.pipeline.AgiPipelineStep")
    currentStep.discussionId = discussionId
    currentStep.parentStepId = parentStepId ?: null
    currentStep.stepSequenceNum = nextSeq
    currentStep.stanceEnumId = normalizedStance
    currentStep.statusId = "PlsExecuting"
    currentStep.stepLabel = stepLabel ?: (directivePrompt.take(50) + "...")
    currentStep.ingressPayloadId = ingressPayloadId ?: null
    currentStep.directivePrompt = directivePrompt
    currentStep.targetArtifactUri = targetArtifactUri ?: disc.targetArtifactUri
    currentStep.createdDate = ec.user.nowTimestamp
    currentStep.setSequencedIdPrimary()
    currentStep.create()
    ec.logger.info("📝 [recordAndDispatch#PipelineStep] Created new AgiPipelineStep #${currentStep.pipelineStepId} [Seq ${nextSeq}, Status: PlsExecuting]")
}

context.pipelineStepId = currentStep.pipelineStepId

// ---------------------------------------------------------------------
// GUARDRAIL: JIT Component Directory & Skeleton Verification
// ---------------------------------------------------------------------
String targetUri = currentStep.targetArtifactUri ?: targetArtifactUri
if (targetUri && targetUri.startsWith("component://")) {
    String cleanComp = targetUri.replace("component://", "").split("/")[0]
    File compDir = new File("runtime/component/" + cleanComp)

    if (!compDir.exists()) {
        ec.logger.warn("⚠️ [recordAndDispatch#PipelineStep] Component directory '${cleanComp}' does not exist on disk. Auto-scaffolding skeleton...")
        try {
            ec.service.sync().name("org.moqui.ide.ComponentServices.create#Component").parameters([
                componentName : cleanComp,
                preset        : "mantle-domain",
                description   : "Auto-scaffolded skeleton for ${cleanComp}"
            ]).call()
            ec.logger.info("✅ [recordAndDispatch#PipelineStep] Successfully scaffolded component '${cleanComp}' on disk prior to BUILD.")
        } catch (Exception scaffoldEx) {
            ec.logger.error("❌ [recordAndDispatch#PipelineStep] Failed to auto-scaffold component '${cleanComp}': ${scaffoldEx.message}", scaffoldEx)
            currentStep.statusId = "PlsFailed"
            currentStep.update()
            context.statusId = "PlsFailed"
            ec.message.addError("Target component '${cleanComp}' does not exist on disk and could not be scaffolded: ${scaffoldEx.message}")
            return
        }
    }
}

// 2. Locate parent message if a parent step exists
String effectiveParentStepId = currentStep.parentStepId ?: parentStepId
String parentMsgId = null
if (effectiveParentStepId) {
    def pStep = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
        .condition("pipelineStepId", effectiveParentStepId)
        .one()
    parentMsgId = pStep?.assistantMessageId ?: pStep?.userMessageId
    ec.logger.info("🔗 [recordAndDispatch#PipelineStep] Parent Step #${effectiveParentStepId} mapped to parent message #${parentMsgId}")
}

// 3. Record the User prompt message for audit trail
Map userTurnResult = ec.service.sync()
    .name("org.moqui.ai.discussion.AgiDiscussionServices.record#DiscussionTurn")
    .parameters([
        discussionId      : discussionId,
        parentMessageId   : parentMsgId,
        senderRoleEnumId  : "AsrUser",
        content           : directivePrompt,
        title             : "Directive #${currentStep.pipelineStepId}",
        targetArtifactUri : currentStep.targetArtifactUri
    ])
    .call()
String userMsgId = userTurnResult.messageId
currentStep.userMessageId = userMsgId
currentStep.update()
ec.logger.info("👤 [recordAndDispatch#PipelineStep] Saved User AgiMessage #${userMsgId}")

// 4. Dispatch the AI execution turn with exponential backoff retry
ec.logger.info("⚡ [recordAndDispatch#PipelineStep] Calling dispatch#AgentTurn with mode='${modeCode}', aiProfile='${effectiveProfile}'...")
Map dispatchResult = [:]
int maxRetries = 3
int attempt = 0
long baseBackoffMs = 2000L
boolean callSucceeded = false

while (attempt < maxRetries && !callSucceeded) {
    attempt++
    try {
        if (attempt > 1) {
            ec.logger.warn("🔄 [recordAndDispatch#PipelineStep] Retrying dispatch#AgentTurn (Attempt ${attempt}/${maxRetries})...")
        }
        // Ingress Payload Resolution & Prompt Hydration
        String effectivePrompt = directivePrompt
        String resolvedIngressId = currentStep.ingressPayloadId ?: ingressPayloadId

        if (!resolvedIngressId && effectiveParentStepId) {
            def pStep = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
                .condition("pipelineStepId", effectiveParentStepId)
                .one()
            resolvedIngressId = pStep?.egressPayloadId ?: pStep?.ingressPayloadId
        }

        if (resolvedIngressId) {
            currentStep.ingressPayloadId = resolvedIngressId
            def ingPayload = ec.entity.find("org.moqui.ai.payload.AgiPayload")
                .condition("agiPayloadId", resolvedIngressId)
                .one()

            if (ingPayload?.payloadJsonData) {
                try {
                    def slurper = new groovy.json.JsonSlurper()
                    def parsedIngress = slurper.parseText(ingPayload.payloadJsonData)

                    if (parsedIngress instanceof Map && parsedIngress.message instanceof String && parsedIngress.message.trim().startsWith('{')) {
                        def inner = slurper.parseText(parsedIngress.message)
                        if (inner instanceof Map) parsedIngress.putAll(inner)
                    }
                    if (parsedIngress instanceof Map && parsedIngress.planDetails instanceof String && parsedIngress.planDetails.trim().startsWith('{')) {
                        def innerPlan = slurper.parseText(parsedIngress.planDetails)
                        if (innerPlan instanceof Map) parsedIngress.putAll(innerPlan)
                    }

                    List upstreamModules = parsedIngress.proposedModules ?: parsedIngress.subplans ?: []
                    List upstreamEntities = parsedIngress.suggestedEntities ?: []
                    String upstreamArch = parsedIngress.architectureSummary ?: parsedIngress.replyMessage ?: ""
                    String recArchetype = parsedIngress.recommendedArchetype ?: ""

                    StringBuilder contextBlock = new StringBuilder()
                    contextBlock.append("\n\n---\n### Upstream Context Contract (from Payload #${resolvedIngressId}):\n")
                    if (recArchetype) contextBlock.append("- Recommended Archetype: ${recArchetype}\n")
                    if (upstreamEntities) contextBlock.append("- Bound Entities: ${upstreamEntities.join(', ')}\n")
                    if (upstreamModules) {
                        contextBlock.append("- Approved Modules / Subscreens to Implement:\n")
                        upstreamModules.each { mod ->
                            contextBlock.append("  * ${mod.key ?: mod.name}: ${mod.title ?: mod.name} (${mod.suggestedArchetype ?: 'standard'})\n")
                            if (mod.description) contextBlock.append("    Scope: ${mod.description}\n")
                        }
                    }
                    if (upstreamArch) {
                        contextBlock.append("- Architectural Summary / Directives:\n")
                        contextBlock.append("  ${upstreamArch.take(1200).replaceAll('\\n', '\n  ')}\n")
                    }
                    contextBlock.append("---\n")

                    effectivePrompt = directivePrompt + contextBlock.toString()
                } catch (Exception parseEx) {
                    ec.logger.warn("⚠️ [recordAndDispatch#PipelineStep] Could not parse ingress payload #${resolvedIngressId}: ${parseEx.message}")
                }
            }
        }

        dispatchResult = ec.service.sync()
            .name("org.moqui.ai.discussion.AgiDiscussionServices.dispatch#AgentTurn")
            .parameters([
                discussionId    : discussionId,
                userPrompt      : effectivePrompt,
                parentMessageId : userMsgId,
                mode            : modeCode,
                aiProfileName   : effectiveProfile
            ])
            .call()

        String textCandidate = dispatchResult?.completionText ?: ""
        boolean hasTransientError = textCandidate.contains("503") ||
                                   textCandidate.contains("429") ||
                                   textCandidate.contains("UNAVAILABLE") ||
                                   textCandidate.contains("RESOURCE_EXHAUSTED")

        if (hasTransientError && attempt < maxRetries) {
            long sleepMs = baseBackoffMs * attempt
            ec.logger.warn("⚠️ [recordAndDispatch#PipelineStep] LLM reported transient error. Retrying in ${sleepMs}ms...")
            Thread.sleep(sleepMs)
        } else {
            callSucceeded = true
        }
    } catch (Exception ex) {
        String exMsg = ex.message ?: ""
        boolean isRetryable = exMsg.contains("503") ||
                             exMsg.contains("429") ||
                             exMsg.contains("UNAVAILABLE") ||
                             exMsg.contains("timeout") ||
                             exMsg.contains("SocketTimeout")

        if (isRetryable && attempt < maxRetries) {
            long sleepMs = baseBackoffMs * attempt
            Thread.sleep(sleepMs)
        } else {
            ec.logger.error("💥 [recordAndDispatch#PipelineStep] Terminal exception on attempt ${attempt}: ${ex.message}", ex)
            if (dispatchResult == null) dispatchResult = [:]
            dispatchResult.completionText = '{"status":"error","error":"' + exMsg.replace('"', "'") + '"}'
            callSucceeded = true
        }
    }
}

if (dispatchResult == null) dispatchResult = [:]
String asstMsgId = dispatchResult?.assistantMessageId
String agentText = dispatchResult?.completionText ?: '{"status":"error","error":"dispatch#AgentTurn returned no result"}'
String generatedPayloadId = dispatchResult?.stagedPayloadId

// 5. Inspect completion text for failure signatures
boolean isFailed = !agentText || agentText.contains('"status":"error"') || agentText.contains('LLM call failed')

if (isFailed) {
    ec.logger.warn("⚠️ [recordAndDispatch#PipelineStep] Step failed execution. Setting Step #${currentStep.pipelineStepId} to PlsFailed.")
    currentStep.assistantMessageId = asstMsgId
    currentStep.egressPayloadId = null
    currentStep.statusId = "PlsFailed"
    currentStep.lastUpdatedDate = ec.user.nowTimestamp
    currentStep.update()

    context.assistantMessageId = asstMsgId
    context.completionText = agentText
    context.statusId = "PlsFailed"
    context.egressPayloadId = null
    ec.message.addError("LLM Execution failed: " + agentText)
    return
}

// 6. AST Compilation for Build steps
if (agentText && (modeCode == "build" || normalizedStance == "AamBuild")) {
    try {
        if (agentText.trim().startsWith("{") && agentText.trim().endsWith("}")) {
            def parsed = new groovy.json.JsonSlurper().parseText(agentText) as Map
            if (parsed.astTree && !parsed.rawXmlContent) {
                Map toXmlResult = ec.service.sync()
                    .name("org.moqui.ide.AgiIdeServices.compile#TreeToXml")
                    .parameters([layoutTree: parsed.astTree])
                    .call()

                String compiledXml = toXmlResult?.xmlText
                if (compiledXml && compiledXml.trim()) {
                    parsed.rawXmlContent = compiledXml
                    agentText = groovy.json.JsonOutput.toJson(parsed)
                }
            }
        }
    } catch (Exception xmlEx) {
        ec.logger.warn("⚠️ [recordAndDispatch#PipelineStep] Could not auto-compile astTree to XML: ${xmlEx.message}")
    }
}

context.assistantMessageId = asstMsgId
context.completionText = agentText

// 7. Store Egress Payload if not already created
if (!generatedPayloadId && agentText) {
    def fallbackPayload = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload")
    fallbackPayload.modeEnumId = normalizedStance
    fallbackPayload.statusId = "PlsCommitted"
    fallbackPayload.targetComponent = comp
    fallbackPayload.artifactUri = currentStep.targetArtifactUri
    fallbackPayload.discussionId = discussionId
    fallbackPayload.messageId = asstMsgId
    fallbackPayload.title = "Step #${currentStep.pipelineStepId} Egress"
    fallbackPayload.userPromptText = directivePrompt
    fallbackPayload.payloadJsonData = agentText
    fallbackPayload.createdDate = ec.user.nowTimestamp
    fallbackPayload.setSequencedIdPrimary()
    fallbackPayload.create()
    generatedPayloadId = fallbackPayload.agiPayloadId
}

// 8. Finalize the Step with Egress Payload and Complete
currentStep.assistantMessageId = asstMsgId
currentStep.egressPayloadId = generatedPayloadId
currentStep.statusId = "PlsCommitted"
currentStep.lastUpdatedDate = ec.user.nowTimestamp
currentStep.update()

context.egressPayloadId = generatedPayloadId
context.statusId = "PlsCommitted"
ec.logger.info("✅ [recordAndDispatch#PipelineStep] Finalized Step #${currentStep.pipelineStepId} (Status: PlsCommitted, Egress: #${generatedPayloadId})")

ec.logger.info("🔱 [fork#PipelineStep] Processing fork/advance (sourceStepId: #${sourceStepId}, discussionId: #${discussionId})...")
def srcStep = null if (sourceStepId) { srcStep = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep") .condition("pipelineStepId", sourceStepId) .one() }
String discId = srcStep?.discussionId ?: discussionId if (!discId) { ec.logger.error("❌ [fork#PipelineStep] Neither sourceStepId nor discussionId was provided!") ec.message.addError("Either sourceStepId or discussionId is required") return }
// If sourceStepId was not provided, look for existing latest step in this discussion if (!srcStep) { srcStep = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep") .condition("discussionId", discId) .orderBy("-stepSequenceNum") .limit(1) .one() }
// If discussion is completely empty, initialize a root discuss step if (!srcStep) { def discRec = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion") .condition("discussionId", discId) .one() String comp = discRec?.targetComponent ?: "nursinghome"
srcStep = ec.entity.makeValue("org.moqui.ai.pipeline.AgiPipelineStep") srcStep.discussionId = discId srcStep.parentStepId = null srcStep.stepSequenceNum = 1 srcStep.stanceEnumId = "AamDiscuss" srcStep.statusId = "PlsCommitted" srcStep.stepLabel = "Initiative Root" srcStep.directivePrompt = "Initial discussion root for ${comp}" srcStep.targetArtifactUri = discRec?.targetArtifactUri srcStep.createdDate = ec.user.nowTimestamp srcStep.setSequencedIdPrimary() srcStep.create() ec.logger.info("🌱 [fork#PipelineStep] Created root step #${srcStep.pipelineStepId} for empty discussion #${discId}") }
String parentId = srcStep.pipelineStepId
String rawStance = targetStanceEnumId ?: stanceEnumId ?: srcStep.stanceEnumId String effectiveStance = "AamPlan" if (rawStance in ["AamBuild", "build"]) effectiveStance = "AamBuild" else if (rawStance in ["AamDiscuss", "discuss"]) effectiveStance = "AamDiscuss" else if (rawStance in ["AamPlan", "plan"]) effectiveStance = "AamPlan"
String activeIngressId = ingressPayloadId ?: (srcStep.egressPayloadId ?: srcStep.ingressPayloadId)
if (modifiedPayloadJson && modifiedPayloadJson.trim()) { def srcPayload = activeIngressId ? ec.entity.find("org.moqui.ai.payload.AgiPayload") .condition("agiPayloadId", activeIngressId) .one() : null
def clonedPayload = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload") clonedPayload.modeEnumId = effectiveStance clonedPayload.statusId = "PlsDraft" clonedPayload.targetComponent = srcPayload?.targetComponent ?: "nursinghome" clonedPayload.artifactUri = srcStep.targetArtifactUri clonedPayload.discussionId = discId clonedPayload.title = "Ingress for Step successor to #${parentId}" clonedPayload.userPromptText = directivePrompt ?: srcStep.directivePrompt clonedPayload.payloadJsonData = modifiedPayloadJson.trim() clonedPayload.parentPayloadId = activeIngressId clonedPayload.createdDate = ec.user.nowTimestamp clonedPayload.setSequencedIdPrimary() clonedPayload.create()
activeIngressId = clonedPayload.agiPayloadId }
int branchSeq = ((srcStep.stepSequenceNum as Integer) ?: 1) + 1 String defaultPrompt = directivePrompt ?: (effectiveStance == "AamBuild" ? "Generate canonical Moqui XML screen and UI artifacts from Plan #${parentId}" : srcStep.directivePrompt)
def forkedStep = ec.entity.makeValue("org.moqui.ai.pipeline.AgiPipelineStep") forkedStep.discussionId = discId forkedStep.parentStepId = parentId forkedStep.stepSequenceNum = branchSeq forkedStep.stanceEnumId = effectiveStance forkedStep.statusId = "PlsDraft" forkedStep.stepLabel = (effectiveStance == "AamBuild" ? "Build from #" : "Branch from #") + parentId forkedStep.ingressPayloadId = activeIngressId forkedStep.directivePrompt = defaultPrompt forkedStep.egressPayloadId = null // Unexecuted forkedStep.targetArtifactUri = srcStep.targetArtifactUri forkedStep.createdDate = ec.user.nowTimestamp forkedStep.setSequencedIdPrimary() forkedStep.create()
context.newStepId = forkedStep.pipelineStepId context.ingressPayloadId = activeIngressId context.statusId = "PlsDraft"
ec.logger.info("🔱 [fork#PipelineStep] Successfully created draft successor Step #${forkedStep.pipelineStepId} [Stance: ${effectiveStance}, Parent: #${parentId}]")

ec.logger.info("⚡ [orchestrate#Module] Starting module orchestration from step #${sourceStepId} with ${subplans?.size() ?: 0} sub-screens...")
def srcStep = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep") .condition("pipelineStepId", sourceStepId) .one() if (!srcStep) { ec.logger.error("❌ [orchestrate#Module] Source step #${sourceStepId} not found!") ec.message.addError("Source Step ${sourceStepId} not found") return }
String discId = srcStep.discussionId String activeIngressId = srcStep.egressPayloadId ?: srcStep.ingressPayloadId List spawnedIds = []
subplans.eachWithIndex { Map sub, int idx -> String title = sub.title ?: sub.name ?: "Sub-Screen ${idx + 1}" String key = sub.key ?: "sub_${idx + 1}" String archetype = sub.suggestedArchetype ?: sub.archetype ?: "master-detail" String targetUri = sub.targetArtifactUri ?: (srcStep.targetArtifactUri ? "${srcStep.targetArtifactUri.replaceAll('\.xml$', '')}/${title.replaceAll('\s+', '')}.xml" : "")
String directive = sub.directivePrompt if (!directive) { directive = "Orchestrate canonical implementation plan for '${title}' (${key}) subscreen.

" + "Target Screen: ${targetUri}
" + "Archetype: ${archetype}
" + (sub.description ? "Scope: ${sub.description}
" : "") + "Requirements:
" + "- Declare screen parameters and transitions adhering to xml-screen-3.xsd
" + "- Bind canonical Mantle UDM entities
" + "- Enforce HIPAA access rules and view permissions" }
Map forkResult = ec.service.sync() .name("org.moqui.ai.pipeline.AgiPipelineServices.fork#PipelineStep") .parameters([ sourceStepId : sourceStepId, targetStanceEnumId : targetStanceEnumId ?: "AamPlan", ingressPayloadId : activeIngressId, directivePrompt : directive ]) .call()
String newId = forkResult.newStepId if (newId) { spawnedIds.add(newId) def stepVal = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep") .condition("pipelineStepId", newId) .one() if (stepVal) { stepVal.stepLabel = "Plan: ${title}" if (targetUri) stepVal.targetArtifactUri = targetUri stepVal.update() } } }
context.spawnedStepIds = spawnedIds context.spawnedCount = spawnedIds.size()

def step = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
    .condition("pipelineStepId", pipelineStepId)
    .one()
if (!step) {
    ec.message.addError("Pipeline step #${pipelineStepId} not found.")
    return
}

String oldDiscussionId = step.discussionId
def oldDisc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
    .condition("discussionId", oldDiscussionId)
    .one()

// 1. Create New Root AgiDiscussion Record
String defaultTitle = discussionName ?: (step.stepLabel ?: "Extracted: Step #${step.pipelineStepId}")
def newDisc = ec.entity.makeValue("org.moqui.ai.discussion.AgiDiscussion")
newDisc.name = defaultTitle
newDisc.shortName = defaultTitle.take(30)
newDisc.targetComponent = oldDisc?.targetComponent ?: "nursinghome"
newDisc.targetArtifactUri = step.targetArtifactUri ?: oldDisc?.targetArtifactUri
newDisc.discussionCategoryEnumId = "AitCategoryInstance"
newDisc.discussionTypeEnumId = "AitDiscElicitation"
newDisc.statusId = "AgdStatusActive"
newDisc.fromDate = ec.user.nowTimestamp
newDisc.messageCount = 0
newDisc.setSequencedIdPrimary()
newDisc.create()

String newDiscId = newDisc.discussionId
context.newDiscussionId = newDiscId

// Copy facets from parent discussion
if (oldDiscussionId) {
    def facets = ec.entity.find("org.moqui.ai.discussion.AgiDiscussionFacet")
        .condition("discussionId", oldDiscussionId)
        .list()
    facets.each { f ->
        def newFacet = ec.entity.makeValue("org.moqui.ai.discussion.AgiDiscussionFacet")
        newFacet.discussionId = newDiscId
        newFacet.facetKey = f.facetKey
        newFacet.facetValue = f.facetValue
        newFacet.facetTypeEnumId = f.facetTypeEnumId
        newFacet.setSequencedIdPrimary()
        newFacet.create()
    }
}

// 2. Collect steps to migrate
List stepsToMigrate = [step]
if (includeBranch) {
    def collectDescendants
    collectDescendants = { String parentId ->
        def children = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
            .condition("parentStepId", parentId)
            .list()
        children.each { child ->
            stepsToMigrate.add(child)
            collectDescendants(child.pipelineStepId as String)
        }
    }
    collectDescendants(step.pipelineStepId as String)
}

// 3. Re-anchor Step(s) to New Discussion
// Detach root extracted step from previous parent
step.parentStepId = null

int seq = 1
stepsToMigrate.each { s ->
    s.discussionId = newDiscId
    s.stepSequenceNum = seq++
    s.lastUpdatedDate = ec.user.nowTimestamp
    s.update()

    // Re-link payloads associated with this step
    if (s.ingressPayloadId) {
        def ip = ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", s.ingressPayloadId).one()
        if (ip) { ip.discussionId = newDiscId; ip.update() }
    }
    if (s.egressPayloadId) {
        def ep = ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", s.egressPayloadId).one()
        if (ep) { ep.discussionId = newDiscId; ep.update() }
    }

    // Re-link user and assistant messages
    if (s.userMessageId) {
        def um = ec.entity.find("org.moqui.ai.discussion.AgiMessage").condition("messageId", s.userMessageId).one()
        if (um) { um.discussionId = newDiscId; um.update() }
    }
    if (s.assistantMessageId) {
        def am = ec.entity.find("org.moqui.ai.discussion.AgiMessage").condition("messageId", s.assistantMessageId).one()
        if (am) { am.discussionId = newDiscId; am.update() }
    }
}

newDisc.messageCount = stepsToMigrate.size()
newDisc.update()

context.migratedStepCount = stepsToMigrate.size()
ec.logger.info("📦 [promote#PipelineStepToDiscussion] Promoted step #${pipelineStepId} (${stepsToMigrate.size()} steps) to new AgiDiscussion #${newDiscId}")
